-- Pact's first durable agreement schema. Amounts are integer minor units.
create table payees (id text primary key, event_id text not null, name text not null, normalized_email text not null, user_id text, created_at timestamptz not null, updated_at timestamptz not null, unique(event_id, normalized_email));
create table payment_agreements (id text primary key, event_id text not null, expense_id text not null unique, organizer_user_id text not null, payee_id text not null references payees(id), payee_email text not null, payee_user_id text, total_amount_minor bigint not null check(total_amount_minor > 0), currency varchar(3) not null, status text not null check(status in ('draft','awaiting_acceptance','active','declined','cancelled','completed')), snapshot jsonb not null, agreement_hash bytea not null, schedule_hash bytea not null, organizer_address varchar(42), payee_address varchar(42), organizer_signature bytea, payee_signature bytea, registration_status text not null, accepted_at timestamptz, declined_at timestamptz, cancelled_at timestamptz, created_at timestamptz not null, updated_at timestamptz not null);
create index payment_agreements_payee_email_idx on payment_agreements(payee_email, status);
create table invoices (id text primary key, event_id text not null, direction text not null check(direction in ('receivable','payable')), funding_source_id text, agreement_id text references payment_agreements(id), invoice_number text not null unique, snapshot jsonb not null, amount_minor bigint not null check(amount_minor > 0), currency varchar(3) not null, status text not null check(status in ('prepared','issued','confirmed','paid','voided')), document_hash bytea not null, confirmed_at timestamptz, paid_at timestamptz, created_at timestamptz not null, updated_at timestamptz not null);
create table pact_accounts (user_id text primary key, signing_address varchar(42) not null unique, credential_metadata jsonb not null, created_at timestamptz not null, updated_at timestamptz not null);
create table payout_profiles (user_id text primary key, signing_address varchar(42) not null, payout_type text not null check(payout_type in ('mera','external_wallet')), payout_address varchar(42) not null, verification_status text not null check(verification_status in ('pending','verified')), verified_at timestamptz, updated_at timestamptz not null);
create table agreement_registration_attempts (id bigserial primary key, agreement_id text not null references payment_agreements(id), attempt_number integer not null, status text not null, transaction_hash varchar(66), failure_code text, failure_message text, created_at timestamptz not null, unique(agreement_id, attempt_number));
